import { test } from 'node:test';
import assert from 'node:assert/strict';
import { compare, sortVersions } from '../semver.js';
test('numeric', () => { assert.equal(compare('1.2.10', '1.2.9'), 1); assert.equal(compare('1.0.0', '1.0.0'), 0); assert.equal(compare('0.9.0', '1.0.0'), -1); });
test('prerelease', () => {
  const order = ['1.0.0-alpha', '1.0.0-alpha.1', '1.0.0-alpha.beta', '1.0.0-beta', '1.0.0-beta.2', '1.0.0-beta.11', '1.0.0-rc.1', '1.0.0'];
  const shuffled = [...order].reverse();
  assert.deepEqual(sortVersions(shuffled), order);
  assert.deepEqual(shuffled, [...order].reverse(), 'input untouched');
});

