function parse(v) {
  const [core, pre] = v.split('-', 2).length === 2 ? [v.slice(0, v.indexOf('-')), v.slice(v.indexOf('-') + 1)] : [v, undefined];
  return { nums: core.split('.').map(Number), pre: pre === undefined ? null : pre.split('.') };
}
function cmpId(x, y) {
  const nx = /^\d+$/.test(x), ny = /^\d+$/.test(y);
  if (nx && ny) return Math.sign(Number(x) - Number(y));
  if (nx) return -1;
  if (ny) return 1;
  return x < y ? -1 : x > y ? 1 : 0;
}
export function compare(a, b) {
  const A = parse(a), B = parse(b);
  for (let i = 0; i < 3; i++) if (A.nums[i] !== B.nums[i]) return A.nums[i] < B.nums[i] ? -1 : 1;
  if (!A.pre && !B.pre) return 0;
  if (!A.pre) return 1;
  if (!B.pre) return -1;
  for (let i = 0; i < Math.min(A.pre.length, B.pre.length); i++) { const c = cmpId(A.pre[i], B.pre[i]); if (c) return c; }
  return Math.sign(A.pre.length - B.pre.length);
}
export function sortVersions(list) { return [...list].sort(compare); }
